onClick.raw:
{(e) => {
                const pane = (e.currentTarget as HTMLElement).closest(
                  ".page-layout-content",
                ) as HTMLElement | null;
                const scrollTop = pane?.scrollTop ?? 0;
                setActiveIndex(i);
                onLastReached?.(i === substeps.length - 1);
                requestAnimationFrame(() => {
                  if (pane) pane.scrollTop = scrollTop;
                });
              }}

